#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main() {
	int tc;
	cin >> tc;
    while(tc--){
    int n ;
    cin >> n;
    int m = 3*n;
    vector<ll> a(m);
    for(int i = 0 ;i<m;i++){
        cin >> a[i];
    }
    sort(a.rbegin(),a.rend());
    vector<ll> pref(m+1,0);
    for(int i = 0 ;i< m;i++){
        pref[i+1]= pref[i]+a[i];
    }
    ll ans= 0;
    for(int A=0;A<=n;A++){
        int lo=0;
        int hi=n-A;
        
        while(lo<hi){
            int B=(lo+hi)/2;
            int k =A+2*B;
            int yxz =3*n - 2*A-B;
            ll left=pref[k+2]-pref[k];
            ll right= 3LL*a[yxz-1];
            
            if(left>=right){
                lo=B+1;}
                
                else{
                hi = B;
                    
                }
        }
                
                for(int B = max(0,lo-1);B<=min(n-A,lo);B++){
                    int C=n-A-B;
                    int first = A;
                    int second =A+2*B;
                    int third = second+3*C;
                    ll cur=0;
                    cur+=6LL*pref[first];
                    cur+=4LL*(pref[second]-pref[first]);
                    cur+=3LL*(pref[third]-pref[second]);
                    ans = max(ans,cur);
                }
    
    }
     cout << ans << endl;
    }
return 0;
}
